class role_editor_controller_default extends Controller {
  static targets = [
    "rolesData",
    "roleList",
    "emptyState",
    "editorForm",
    "editorTitle",
    "deleteBtn",
    "nameInput",
    "colorInput",
    "colorHex",
    "permissionsSection",
    "saveBar",
    "roleName"
  ];
  static values = { serverId: String, canManage: Boolean };
  connect() {
    this.roles = JSON.parse(this.rolesDataTarget.textContent);
    this.selectedRoleId = null;
    this.originalData = null;
    this.dirty = false;
    if (this.canManageValue) {
      this.sortable = sortable_esm_default.create(this.roleListTarget, {
        animation: 150,
        ghostClass: "opacity-20",
        chosenClass: "bg-gray-600",
        onEnd: () => this.handleReorder()
      });
    }
  }
  disconnect() {
    if (this.sortable)
      this.sortable.destroy();
  }
  selectRole(e) {
    const id = e.currentTarget.dataset.roleId;
    if (id === this.selectedRoleId)
      return;
    if (this.dirty) {
      if (!confirm("You have unsaved changes. Discard them?"))
        return;
    }
    this.selectedRoleId = id;
    const role = this.roles.find((r) => r.id === id);
    if (!role)
      return;
    this.originalData = JSON.parse(JSON.stringify(role));
    this.dirty = false;
    this.saveBarTarget.classList.add("hidden");
    this.roleListTarget.querySelectorAll("[data-role-id]").forEach((el) => {
      el.classList.toggle("bg-gray-600", el.dataset.roleId === id);
      el.classList.toggle("bg-gray-800", el.dataset.roleId !== id);
    });
    this.populateEditor(role);
  }
  populateEditor(role) {
    this.editorFormTarget.classList.remove("hidden");
    this.emptyStateTarget.classList.add("hidden");
    this.editorTitleTarget.textContent = role.name;
    this.roleNameTarget.textContent = role.name;
    if (role.is_owner || role.is_everyone) {
      this.deleteBtnTarget.classList.add("hidden");
    } else {
      this.deleteBtnTarget.classList.remove("hidden");
    }
    this.nameInputTarget.value = role.name;
    this.colorInputTarget.value = role.color || "#99aab5";
    this.colorHexTarget.textContent = (role.color || "#99aab5").toUpperCase();
    const disableDisplay = role.is_everyone || role.is_owner;
    this.nameInputTarget.disabled = disableDisplay;
    this.colorInputTarget.disabled = disableDisplay;
    if (disableDisplay) {
      this.nameInputTarget.classList.add("opacity-50");
      this.colorInputTarget.classList.add("opacity-50");
    } else {
      this.nameInputTarget.classList.remove("opacity-50");
      this.colorInputTarget.classList.remove("opacity-50");
    }
    const hoistToggle = this.element.querySelector("[data-hoist-toggle]");
    if (hoistToggle) {
      if (role.is_everyone || role.is_owner) {
        hoistToggle.closest("[data-hoist-row]").classList.add("hidden");
      } else {
        hoistToggle.closest("[data-hoist-row]").classList.remove("hidden");
        if (role.hoist) {
          hoistToggle.classList.remove("bg-gray-600");
          hoistToggle.classList.add("bg-orange-600");
          hoistToggle.firstElementChild.classList.remove("translate-x-0.5");
          hoistToggle.firstElementChild.classList.add("translate-x-5");
        } else {
          hoistToggle.classList.remove("bg-orange-600");
          hoistToggle.classList.add("bg-gray-600");
          hoistToggle.firstElementChild.classList.remove("translate-x-5");
          hoistToggle.firstElementChild.classList.add("translate-x-0.5");
        }
      }
    }
    this.renderPermissions(role);
  }
  renderPermissions(role) {
    const container = this.permissionsSectionTarget;
    container.innerHTML = "";
    if (role.is_owner) {
      container.innerHTML = '<p class="text-sm text-gray-500 italic">The Owner role has all permissions and cannot be edited.</p>';
      return;
    }
    for (const [groupName, perms] of Object.entries(PERMISSION_GROUPS)) {
      const groupDiv = document.createElement("div");
      groupDiv.className = "mb-6";
      const heading = document.createElement("h4");
      heading.className = "text-xs font-bold text-gray-400 uppercase tracking-wide mb-3";
      heading.textContent = groupName;
      groupDiv.appendChild(heading);
      for (const [key, description] of Object.entries(perms)) {
        const enabled = role.permissions && role.permissions[key] === true;
        const row = document.createElement("div");
        row.className = "flex items-center justify-between py-2 border-b border-gray-700/50";
        const labelDiv = document.createElement("div");
        labelDiv.className = "flex-1 mr-4";
        const label = document.createElement("p");
        label.className = "text-sm text-white";
        label.textContent = key.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
        labelDiv.appendChild(label);
        const desc = document.createElement("p");
        desc.className = "text-xs text-gray-500";
        desc.textContent = description;
        labelDiv.appendChild(desc);
        row.appendChild(labelDiv);
        const toggle = document.createElement("button");
        toggle.type = "button";
        toggle.className = `relative w-11 h-6 rounded-full transition-colors focus:outline-none ${enabled ? "bg-orange-600" : "bg-gray-600"}`;
        toggle.dataset.permission = key;
        toggle.dataset.action = "click->role-editor#togglePermission";
        const knob = document.createElement("span");
        knob.className = `block w-5 h-5 bg-white rounded-full shadow transform transition-transform ${enabled ? "translate-x-5" : "translate-x-0.5"}`;
        toggle.appendChild(knob);
        row.appendChild(toggle);
        groupDiv.appendChild(row);
      }
      container.appendChild(groupDiv);
    }
  }
  togglePermission(e) {
    const btn = e.currentTarget;
    const key = btn.dataset.permission;
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (!role)
      return;
    const newVal = !(role.permissions && role.permissions[key] === true);
    if (!role.permissions)
      role.permissions = {};
    role.permissions[key] = newVal;
    if (newVal) {
      btn.classList.remove("bg-gray-600");
      btn.classList.add("bg-orange-600");
      btn.firstElementChild.classList.remove("translate-x-0.5");
      btn.firstElementChild.classList.add("translate-x-5");
    } else {
      btn.classList.remove("bg-orange-600");
      btn.classList.add("bg-gray-600");
      btn.firstElementChild.classList.remove("translate-x-5");
      btn.firstElementChild.classList.add("translate-x-0.5");
    }
    this.markDirty();
  }
  toggleHoist(e) {
    const btn = e.currentTarget;
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (!role)
      return;
    role.hoist = !role.hoist;
    if (role.hoist) {
      btn.classList.remove("bg-gray-600");
      btn.classList.add("bg-orange-600");
      btn.firstElementChild.classList.remove("translate-x-0.5");
      btn.firstElementChild.classList.add("translate-x-5");
    } else {
      btn.classList.remove("bg-orange-600");
      btn.classList.add("bg-gray-600");
      btn.firstElementChild.classList.remove("translate-x-5");
      btn.firstElementChild.classList.add("translate-x-0.5");
    }
    this.markDirty();
  }
  previewColor() {
    const color = this.colorInputTarget.value;
    this.colorHexTarget.textContent = color.toUpperCase();
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (role)
      role.color = color;
    const listItem = this.roleListTarget.querySelector(`[data-role-id="${this.selectedRoleId}"]`);
    if (listItem) {
      const dot = listItem.querySelector("[data-color-dot]");
      if (dot)
        dot.style.backgroundColor = color;
    }
    this.markDirty();
  }
  updateName() {
    const name = this.nameInputTarget.value;
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (role)
      role.name = name;
    const listItem = this.roleListTarget.querySelector(`[data-role-id="${this.selectedRoleId}"]`);
    if (listItem) {
      const nameEl = listItem.querySelector("[data-role-name]");
      if (nameEl)
        nameEl.textContent = name;
    }
    this.editorTitleTarget.textContent = name;
    this.roleNameTarget.textContent = name;
    this.markDirty();
  }
  markDirty() {
    this.dirty = true;
    this.saveBarTarget.classList.remove("hidden");
  }
  resetChanges() {
    if (!this.originalData)
      return;
    const idx = this.roles.findIndex((r) => r.id === this.selectedRoleId);
    if (idx !== -1) {
      this.roles[idx] = JSON.parse(JSON.stringify(this.originalData));
    }
    this.dirty = false;
    this.saveBarTarget.classList.add("hidden");
    this.populateEditor(this.roles[idx]);
    const listItem = this.roleListTarget.querySelector(`[data-role-id="${this.selectedRoleId}"]`);
    if (listItem) {
      const dot = listItem.querySelector("[data-color-dot]");
      if (dot)
        dot.style.backgroundColor = this.originalData.color || "#99aab5";
      const nameEl = listItem.querySelector("[data-role-name]");
      if (nameEl)
        nameEl.textContent = this.originalData.name;
    }
  }
  async saveRole() {
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (!role)
      return;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/roles/${role.id}`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({
          name: role.name,
          color: role.color,
          hoist: role.hoist,
          permissions: role.permissions
        })
      });
      if (res.ok) {
        const updated = await res.json();
        const idx = this.roles.findIndex((r) => r.id === this.selectedRoleId);
        if (idx !== -1)
          this.roles[idx] = updated;
        this.originalData = JSON.parse(JSON.stringify(updated));
        this.dirty = false;
        this.saveBarTarget.classList.add("hidden");
        this.showToast("Role saved!");
      } else {
        const data = await res.json();
        this.showToast(data.error || data.errors?.join(", ") || "Save failed", true);
      }
    } catch (err) {
      this.showToast("Network error", true);
    }
  }
  async createRole() {
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/roles`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({})
      });
      if (res.ok) {
        const role = await res.json();
        this.roles.push(role);
        this.appendRoleToList(role);
        this.selectedRoleId = role.id;
        this.originalData = JSON.parse(JSON.stringify(role));
        this.dirty = false;
        this.saveBarTarget.classList.add("hidden");
        this.roleListTarget.querySelectorAll("[data-role-id]").forEach((el) => {
          el.classList.toggle("bg-gray-600", el.dataset.roleId === role.id);
          el.classList.toggle("bg-gray-800", el.dataset.roleId !== role.id);
        });
        this.populateEditor(role);
        this.showToast("Role created!");
      } else {
        const data = await res.json();
        this.showToast(data.errors?.join(", ") || "Create failed", true);
      }
    } catch (err) {
      this.showToast("Network error", true);
    }
  }
  async deleteRole() {
    const role = this.roles.find((r) => r.id === this.selectedRoleId);
    if (!role || role.is_owner || role.is_everyone)
      return;
    if (!confirm(`Delete "${role.name}"? Members with this role will be moved to @everyone.`))
      return;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/roles/${role.id}`, {
        method: "DELETE",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (res.ok) {
        this.roles = this.roles.filter((r) => r.id !== role.id);
        const listItem = this.roleListTarget.querySelector(`[data-role-id="${role.id}"]`);
        if (listItem)
          listItem.remove();
        this.selectedRoleId = null;
        this.originalData = null;
        this.dirty = false;
        this.editorFormTarget.classList.add("hidden");
        this.emptyStateTarget.classList.remove("hidden");
        this.saveBarTarget.classList.add("hidden");
        this.showToast("Role deleted!");
      } else {
        const data = await res.json();
        this.showToast(data.error || "Delete failed", true);
      }
    } catch (err) {
      this.showToast("Network error", true);
    }
  }
  async handleReorder() {
    const items = this.roleListTarget.querySelectorAll("[data-role-id]");
    const rolesPayload = [];
    const sortableItems = Array.from(items);
    const maxPos = sortableItems.length;
    sortableItems.forEach((el, idx) => {
      const pos = maxPos - idx;
      rolesPayload.push({ id: el.dataset.roleId, position: pos });
      const role = this.roles.find((r) => r.id === el.dataset.roleId);
      if (role)
        role.position = pos;
    });
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/reorder_roles`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({ roles: rolesPayload })
      });
      if (res.ok) {
        this.showToast("Role order saved!");
      } else {
        this.showToast("Failed to save order", true);
      }
    } catch (err) {
      this.showToast("Network error", true);
    }
  }
  appendRoleToList(role) {
    const item = document.createElement("div");
    item.className = "flex items-center px-3 py-2 rounded cursor-pointer bg-gray-800 hover:bg-gray-700 transition-colors";
    item.dataset.roleId = role.id;
    item.dataset.action = "click->role-editor#selectRole";
    item.innerHTML = `
      <span class="w-3 h-3 rounded-full mr-3 shrink-0" data-color-dot style="background-color: ${this.escapeHtml(role.color || "#99aab5")}"></span>
      <span class="flex-1 text-sm text-white truncate" data-role-name>${this.escapeHtml(role.name)}</span>
      <span class="text-xs text-gray-500 ml-2">${role.member_count}</span>
    `;
    const everyoneItem = Array.from(this.roleListTarget.children).find((el) => {
      const role2 = this.roles.find((r) => r.id === el.dataset.roleId);
      return role2 && role2.is_everyone;
    });
    if (everyoneItem) {
      this.roleListTarget.insertBefore(item, everyoneItem);
    } else {
      this.roleListTarget.appendChild(item);
    }
  }
  escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }
  showToast(msg, isError = false) {
    const toast = document.createElement("div");
    toast.className = `fixed bottom-6 right-6 ${isError ? "bg-red-600" : "bg-green-600"} text-white px-4 py-2 rounded-lg shadow-lg z-[200] text-sm font-medium context-pop`;
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.style.transition = "opacity 0.3s";
      toast.style.opacity = "0";
      setTimeout(() => toast.remove(), 300);
    }, 2000);
  }
}

// app/javascript/controllers/member_roles_controller.js
class member_roles_controller_default extends Controller {
  static values = {
    serverId: String,
    membershipId: String,
    allRoles: Array,
    currentRoleIds: Array
  };
  static targets = ["dropdown", "badges"];
  connect() {
    this.boundCloseDropdown = this.closeDropdown.bind(this);
  }
  disconnect() {
    document.removeEventListener("click", this.boundCloseDropdown);
  }
  toggle(event) {
    event.stopPropagation();
    const dropdown = this.dropdownTarget;
    const isHidden = dropdown.classList.contains("hidden");
    if (isHidden) {
      dropdown.classList.remove("hidden");
      setTimeout(() => document.addEventListener("click", this.boundCloseDropdown), 10);
    } else {
      this.closeDropdown();
    }
  }
  closeDropdown(event) {
    if (event && this.dropdownTarget.contains(event.target))
      return;
    this.dropdownTarget.classList.add("hidden");
    document.removeEventListener("click", this.boundCloseDropdown);
  }
  async toggleRole(event) {
    event.stopPropagation();
    const checkboxes = this.dropdownTarget.querySelectorAll("input[type=checkbox]");
    const roleIds = Array.from(checkboxes).filter((cb) => cb.checked).map((cb) => cb.value);
    try {
      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content;
      const response = await fetch(`/servers/${this.serverIdValue}/settings/members/${this.membershipIdValue}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          "X-CSRF-Token": csrfToken
        },
        body: JSON.stringify({ role_ids: roleIds })
      });
      if (!response.ok)
        throw new Error("Failed to update roles");
      const data = await response.json();
      this.updateBadges(data.roles);
      this.showToast("Roles updated", "success");
    } catch (error2) {
      this.showToast("Failed to update roles", "error");
    }
  }
  updateBadges(roles) {
    const badgesEl = this.badgesTarget;
    if (!badgesEl)
      return;
    if (roles.length === 0) {
      badgesEl.innerHTML = '<span class="inline-flex items-center text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400">@everyone</span>';
      return;
    }
    badgesEl.innerHTML = roles.map((role) => {
      const bgClass = role.name === "Admin" ? "bg-red-600/20 text-red-400" : "bg-gray-700 text-gray-400";
      return `<span class="inline-flex items-center text-xs px-2 py-0.5 rounded-full ${bgClass}">
        <span class="w-2 h-2 rounded-full mr-1" style="background-color: ${role.color || "#ffffff"}"></span>
        ${this.escapeHtml(role.name)}
      </span>`;
    }).join("");
  }
  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
  showToast(message, type) {
    const toast = document.getElementById("toast");
    if (!toast)
      return;
    toast.textContent = message;
    toast.className = `fixed top-4 right-4 px-4 py-2 rounded-lg shadow-lg text-sm font-medium z-[100] transition-opacity duration-300 context-pop ${type === "success" ? "bg-green-600 text-white" : "bg-red-600 text-white"}`;
    toast.classList.remove("hidden", "opacity-0");
    setTimeout(() => {
      toast.classList.add("opacity-0");
      setTimeout(() => toast.classList.add("hidden"), 300);
    }, 3000);
  }
}

// app/javascript/controllers/server_rail_controller.js
class server_rail_controller_default extends Controller {
  static targets = ["list", "folderList"];
  connect() {
    this.sortables = [];
    this.folderMenu = null;
    this.boundCloseMenu = this.closeFolderMenu.bind(this);
    this.boundKeydown = this.handleKeydown.bind(this);
    this.dragOverTarget = null;
    this.folderCreationReady = false;
    this.folderCreationTimer = null;
    if (this.hasListTarget) {
      this.initMainSortable();
      this.initFolderSortables();
    }
    this.freezeGifs();
  }
  disconnect() {
    this.sortables.forEach((s) => s.destroy());
    this.sortables = [];
    this.closeFolderMenu();
    clearTimeout(this.folderCreationTimer);
  }
  initMainSortable() {
    const sortable = sortable_esm_default.create(this.listTarget, {
      animation: 150,
      ghostClass: "opacity-20",
      dragClass: "shadow-lg",
      draggable: "[data-rail-item], [data-server-id]",
      fallbackOnBody: true,
      swapThreshold: 0.65,
      group: "rail",
      onStart: () => this.onDragStart(),
      onEnd: (evt) => this.handleMainDrop(evt),
      onMove: (evt) => this.handleDragMove(evt),
      onAdd: (evt) => {
        evt.item.setAttribute("data-rail-item", "server");
      }
    });
    this.sortables.push(sortable);
  }
  initFolderSortables() {
    this.element.querySelectorAll("[data-folder-server-list]").forEach((list) => {
      this.initSingleFolderSortable(list);
    });
  }
  initSingleFolderSortable(list) {
    if (list._sortableInitialized)
      return;
    const sortable = sortable_esm_default.create(list, {
      animation: 150,
      ghostClass: "opacity-20",
      dragClass: "shadow-lg",
      draggable: "[data-server-id]",
      fallbackOnBody: true,
      swapThreshold: 0.65,
      group: "rail",
      onEnd: () => this.saveOrder(),
      onAdd: (evt) => this.handleFolderAdd(evt),
      onRemove: (evt) => this.handleFolderRemove(evt)
    });
    this.sortables.push(sortable);
    list._sortableInitialized = true;
  }
  onDragStart() {
    this.dragOverTarget = null;
    this.folderCreationReady = false;
    clearTimeout(this.folderCreationTimer);
  }
  handleDragMove(evt) {
    const dragged = evt.dragged;
    const related = evt.related;
    if (!dragged || !related) {
      this.clearFolderCreationState();
      return true;
    }
    if (dragged.dataset.railItem === "folder" || related.dataset.railItem === "folder") {
      this.clearFolderCreationState();
      return true;
    }
    if (!dragged.dataset.serverId || !related.dataset.serverId) {
      this.clearFolderCreationState();
      return true;
    }
    if (related.closest("[data-folder-server-list]")) {
      this.clearFolderCreationState();
      return true;
    }
    if (this.dragOverTarget === related)
      return true;
    this.clearFolderCreationState();
    related.classList.add("folder-drop-target");
    this.dragOverTarget = related;
    this.folderCreationTimer = setTimeout(() => {
      this.folderCreationReady = true;
      if (this.dragOverTarget) {
        this.dragOverTarget.classList.remove("folder-drop-target");
        this.dragOverTarget.classList.add("folder-drop-ready");
      }
    }, 500);
    return true;
  }
  clearFolderCreationState() {
    clearTimeout(this.folderCreationTimer);
    this.folderCreationReady = false;
    if (this.dragOverTarget) {
      this.dragOverTarget.classList.remove("folder-drop-target", "folder-drop-ready");
      this.dragOverTarget = null;
    }
    this.element.querySelectorAll(".folder-drop-target, .folder-drop-ready").forEach((el) => {
      el.classList.remove("folder-drop-target", "folder-drop-ready");
    });
  }
  async handleMainDrop(evt) {
    const shouldCreateFolder = this.folderCreationReady;
    const target = this.dragOverTarget;
    this.clearFolderCreationState();
    const dragged = evt.item;
    if (shouldCreateFolder && target && dragged.dataset.serverId && target.dataset.serverId && dragged !== target && !dragged.dataset.folderId && !target.dataset.folderId) {
      await this.createFolder(dragged.dataset.serverId, target.dataset.serverId, dragged, target);
      return;
    }
    this.saveOrder();
  }
  async createFolder(serverId1, serverId2, el1, el2) {
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    const serverIds = [];
    const remoteServerIds = [];
    [serverId1, serverId2].forEach((id) => {
      if (id.startsWith("r_")) {
        remoteServerIds.push(id.substring(2));
      } else {
        serverIds.push(id);
      }
    });
    try {
      const response = await fetch("/server_folders", {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({
          server_folder: { name: "Folder" },
          server_ids: serverIds,
          remote_server_ids: remoteServerIds
        })
      });
      if (!response.ok)
        return this.saveOrder();
      const data = await response.json();
      const temp = document.createElement("div");
      temp.innerHTML = data.html;
      const folderEl = temp.firstElementChild;
      el1.replaceWith(folderEl);
      el2.remove();
      const newFolderList = folderEl.querySelector("[data-folder-server-list]");
      if (newFolderList) {
        this.initSingleFolderSortable(newFolderList);
      }
      this.freezeGifs();
      this.saveOrder();
    } catch (e) {
      this.saveOrder();
    }
  }
  handleFolderAdd(evt) {
    const folderEl = evt.to.closest("[data-folder-id]");
    if (folderEl)
      this.updateFolderIcons(folderEl);
    this.saveOrder();
  }
  handleFolderRemove(evt) {
    const folderEl = evt.from.closest("[data-folder-id]");
    if (!folderEl)
      return;
    const serverList = folderEl.querySelector("[data-folder-server-list]");
    if (serverList && serverList.children.length === 0) {
      const folderId = folderEl.dataset.folderId;
      folderEl.remove();
      this.deleteFolder(folderId, false);
    } else {
      this.updateFolderIcons(folderEl);
    }
    this.saveOrder();
  }
  updateFolderIcons(folderEl) {
    const serverList = folderEl.querySelector("[data-folder-server-list]");
    if (!serverList)
      return;
    const servers = Array.from(serverList.children).filter((el) => el.dataset.serverId);
    const offsets = [
      { x: -4, y: -4 },
      { x: 6, y: -2 },
      { x: 1, y: 6 }
    ];
    folderEl.querySelectorAll("[data-folder-icons]").forEach((container) => {
      const folderColor = container.dataset.folderColor || "#4f545c";
      container.style.backgroundColor = folderColor;
      container.innerHTML = "";
      servers.slice(0, 3).forEach((serverEl, i) => {
        const offset = offsets[i];
        const mini = document.createElement("div");
        mini.className = "absolute w-5 h-5 rounded-md overflow-hidden border border-gray-800";
        mini.style.transform = `translate(${offset.x}px, ${offset.y}px)`;
        mini.style.zIndex = 3 - i;
        const frozenCanvas = serverEl.querySelector("[data-gif-freeze]");
        const img = serverEl.querySelector("img:not(.gif-animated)");
        if (frozenCanvas && frozenCanvas.width > 0) {
          const miniImg = document.createElement("img");
          try {
            miniImg.src = frozenCanvas.toDataURL();
          } catch (e) {
            miniImg.src = "";
          }
          miniImg.className = "w-full h-full object-cover";
          mini.appendChild(miniImg);
        } else if (img) {
          const miniImg = document.createElement("img");
          miniImg.src = img.src;
          miniImg.className = "w-full h-full object-cover";
          mini.appendChild(miniImg);
        } else {
          const span = serverEl.querySelector("span.text-white");
          const initials = span ? span.textContent.trim() : "?";
          const div = document.createElement("div");
          div.className = "w-full h-full bg-gray-600 flex items-center justify-center";
          div.innerHTML = `<span class="text-white text-[6px] font-bold">${this.escapeAttr(initials)}</span>`;
          mini.appendChild(div);
        }
        container.appendChild(mini);
      });
    });
  }
  toggleFolder(event) {
    event.preventDefault();
    event.stopPropagation();
    const folderEl = event.currentTarget.closest("[data-folder-id]");
    if (!folderEl)
      return;
    const collapsed = folderEl.dataset.collapsed === "true";
    const collapsedView = folderEl.querySelector("[data-folder-collapsed-view]");
    const expandedView = folderEl.querySelector("[data-folder-expanded-view]");
    const container = folderEl.querySelector("[data-folder-server-container]");
    if (collapsed) {
      folderEl.dataset.collapsed = "false";
      collapsedView.classList.add("hidden");
      if (container)
        container.classList.add("folder-grid-collapsed");
      expandedView.classList.remove("hidden");
      if (container) {
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            container.classList.remove("folder-grid-collapsed");
          });
        });
      }
      const serverList = folderEl.querySelector("[data-folder-server-list]");
      if (serverList)
        this.initSingleFolderSortable(serverList);
      setTimeout(() => this.freezeGifs(), 100);
      setTimeout(() => this.freezeGifs(), 500);
    } else {
      if (container) {
        container.classList.add("folder-grid-collapsed");
        setTimeout(() => {
          folderEl.dataset.collapsed = "true";
          collapsedView.classList.remove("hidden");
          expandedView.classList.add("hidden");
        }, 300);
      } else {
        folderEl.dataset.collapsed = "true";
        collapsedView.classList.remove("hidden");
        expandedView.classList.add("hidden");
      }
    }
    const folderId = folderEl.dataset.folderId;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    fetch(`/server_folders/${folderId}/toggle_collapse`, {
      method: "PATCH",
      headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
    });
  }
  showFolderMenu(event) {
    event.preventDefault();
    event.stopPropagation();
    this.closeFolderMenu();
    const folderEl = event.currentTarget.closest("[data-folder-id]");
    if (!folderEl)
      return;
    const folderId = folderEl.dataset.folderId;
    const folderNameEl = folderEl.querySelector("[data-folder-name]");
    const currentName = folderNameEl ? folderNameEl.textContent.trim() : "Folder";
    this.folderMenu = document.createElement("div");
    this.folderMenu.className = "fixed z-[60] w-48 bg-gray-800 rounded-lg shadow-xl border border-gray-600 py-1.5 text-sm context-pop";
    let left = event.clientX;
    let top = event.clientY;
    if (left + 192 > window.innerWidth)
      left = window.innerWidth - 196;
    if (top + 100 > window.innerHeight)
      top = window.innerHeight - 104;
    this.folderMenu.style.left = `${left}px`;
    this.folderMenu.style.top = `${top}px`;
    const currentColor = folderEl.querySelector("[data-folder-color]")?.dataset.folderColor || "#4f545c";
    this.folderMenu.innerHTML = `
      <button data-menu-action="rename" class="w-full text-left px-3 py-1.5 text-gray-300 hover:bg-gray-700 hover:text-white transition">Rename Folder</button>
      <button data-menu-action="color" class="w-full text-left px-3 py-1.5 text-gray-300 hover:bg-gray-700 hover:text-white transition">Folder Color</button>
      <button data-menu-action="delete" class="w-full text-left px-3 py-1.5 text-red-400 hover:bg-gray-700 hover:text-red-300 transition">Delete Folder</button>
    `;
    document.body.appendChild(this.folderMenu);
    this.folderMenu.querySelector("[data-menu-action='rename']").addEventListener("click", (e) => {
      e.stopPropagation();
      this.showRenameInput(folderId, currentName, folderEl);
    });
    this.folderMenu.querySelector("[data-menu-action='color']").addEventListener("click", (e) => {
      e.stopPropagation();
      this.showColorPicker(folderId, currentColor, folderEl);
    });
    this.folderMenu.querySelector("[data-menu-action='delete']").addEventListener("click", (e) => {
      e.stopPropagation();
      this.deleteFolder(folderId, true);
      this.closeFolderMenu();
    });
    setTimeout(() => {
      document.addEventListener("click", this.boundCloseMenu);
      document.addEventListener("keydown", this.boundKeydown);
    }, 10);
  }
  showRenameInput(folderId, currentName, folderEl) {
    if (!this.folderMenu)
      return;
    this.folderMenu.innerHTML = `
      <div class="px-3 py-2">
        <label class="text-[10px] text-gray-500 uppercase font-semibold mb-1 block">Folder Name</label>
        <input type="text" value="${this.escapeAttr(currentName)}" maxlength="50"
               class="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-sm focus:outline-none focus:border-orange-500"
               data-rename-input>
        <button class="mt-2 w-full bg-orange-600 hover:bg-orange-700 text-white text-xs font-semibold py-1 rounded transition" data-rename-save>Save</button>
      </div>
    `;
    const input = this.folderMenu.querySelector("[data-rename-input]");
    input.focus();
    input.select();
    const save2 = () => this.renameFolder(folderId, input.value.trim(), folderEl);
    this.folderMenu.querySelector("[data-rename-save]").addEventListener("click", (e) => {
      e.stopPropagation();
      save2();
    });
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        save2();
      }
      if (e.key === "Escape") {
        this.closeFolderMenu();
      }
    });
    input.addEventListener("click", (e) => e.stopPropagation());
  }
  showColorPicker(folderId, currentColor, folderEl) {
    if (!this.folderMenu)
      return;
    const presets = [
      { color: "#4f545c", label: "Gray" },
      { color: "#b45309", label: "Ember" },
      { color: "#57f287", label: "Green" },
      { color: "#fee75c", label: "Yellow" },
      { color: "#eb459e", label: "Pink" },
      { color: "#ed4245", label: "Red" },
      { color: "#f47b67", label: "Orange" },
      { color: "#9b59b6", label: "Purple" }
    ];
    const swatchesHtml = presets.map((p) => {
      const ring = p.color.toLowerCase() === currentColor.toLowerCase() ? "ring-2 ring-white" : "";
      return `<button data-color-swatch="${p.color}" title="${p.label}" class="w-8 h-8 rounded-full ${ring} hover:scale-110 transition-transform" style="background-color: ${p.color}"></button>`;
    }).join("");
    this.folderMenu.innerHTML = `
      <div class="px-3 py-2">
        <label class="text-[10px] text-gray-500 uppercase font-semibold mb-2 block">Folder Color</label>
        <div class="grid grid-cols-4 gap-2 mb-2">${swatchesHtml}</div>
        <div class="flex items-center gap-2">
          <input type="color" value="${currentColor}" class="w-8 h-8 rounded cursor-pointer border-0 p-0 bg-transparent" data-custom-color>
          <span class="text-xs text-gray-400">Custom</span>
        </div>
      </div>
    `;
    const applyColor = (color) => this.applyFolderColor(folderId, color, folderEl);
    this.folderMenu.querySelectorAll("[data-color-swatch]").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        applyColor(btn.dataset.colorSwatch);
      });
    });
    const customInput = this.folderMenu.querySelector("[data-custom-color]");
    customInput.addEventListener("input", (e) => {
      e.stopPropagation();
      applyColor(customInput.value);
    });
    customInput.addEventListener("click", (e) => e.stopPropagation());
  }
  async applyFolderColor(folderId, color, folderEl) {
    folderEl.querySelectorAll("[data-folder-icons]").forEach((container) => {
      container.style.backgroundColor = color;
      container.dataset.folderColor = color;
    });
    const serverBg = folderEl.querySelector("[data-folder-server-bg]");
    if (serverBg) {
      serverBg.style.backgroundColor = color + "30";
      serverBg.dataset.folderServerBg = color;
    }
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      await fetch(`/server_folders/${folderId}`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({ server_folder: { color } })
      });
    } catch (e) {
    }
    this.closeFolderMenu();
  }
  async renameFolder(folderId, newName, folderEl) {
    if (!newName)
      return;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const response = await fetch(`/server_folders/${folderId}`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({ server_folder: { name: newName } })
      });
      if (response.ok) {
        folderEl.querySelectorAll("[data-folder-name]").forEach((el) => {
          el.textContent = newName;
        });
      }
    } catch (e) {
    }
    this.closeFolderMenu();
  }
  async deleteFolder(folderId, moveServersToDom) {
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    if (moveServersToDom) {
      const folderEl = this.element.querySelector(`[data-folder-id="${folderId}"]`);
      if (folderEl) {
        const serverList = folderEl.querySelector("[data-folder-server-list]");
        if (serverList) {
          Array.from(serverList.children).forEach((serverEl) => {
            serverEl.setAttribute("data-rail-item", "server");
            this.listTarget.insertBefore(serverEl, folderEl);
          });
        }
        folderEl.remove();
      }
    }
    try {
      await fetch(`/server_folders/${folderId}`, {
        method: "DELETE",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
    } catch (e) {
    }
    this.saveOrder();
  }
  parseServerId(rawId) {
    if (rawId && rawId.startsWith("r_")) {
      return { id: rawId.substring(2), remote: true };
    }
    return { id: rawId, remote: false };
  }
  async saveOrder() {
    const items = [];
    let position = 0;
    Array.from(this.listTarget.children).forEach((child) => {
      if (child.dataset.folderId) {
        const folderServers = [];
        const serverList = child.querySelector("[data-folder-server-list]");
        if (serverList) {
          Array.from(serverList.children).forEach((serverEl, idx) => {
            if (serverEl.dataset.serverId) {
              const parsed = this.parseServerId(serverEl.dataset.serverId);
              const entry = { id: parsed.id, position: idx };
              if (parsed.remote)
                entry.remote = true;
              folderServers.push(entry);
            }
          });
        }
        items.push({ type: "folder", id: child.dataset.folderId, position: position++, servers: folderServers });
      } else if (child.dataset.serverId) {
        const parsed = this.parseServerId(child.dataset.serverId);
        if (parsed.remote) {
          items.push({ type: "remote_server", id: parsed.id, position: position++ });
        } else {
          items.push({ type: "server", id: parsed.id, position: position++ });
        }
      }
    });
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    await fetch("/reorder_servers", {
      method: "PATCH",
      headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
      body: JSON.stringify({ items })
    });
  }
  closeFolderMenu(event) {
    if (this.folderMenu) {
      if (event && this.folderMenu.contains(event.target))
        return;
      this.folderMenu.remove();
      this.folderMenu = null;
    }
    document.removeEventListener("click", this.boundCloseMenu);
    document.removeEventListener("keydown", this.boundKeydown);
  }
  handleKeydown(event) {
    if (event.key === "Escape") {
      this.closeFolderMenu();
    }
  }
  freezeGifs() {
    this.element.querySelectorAll(".server-icon-gif, .folder-mini-gif").forEach((el) => {
      const img = el.querySelector("[data-gif-src]");
      const canvas = el.querySelector("[data-gif-freeze]");
      if (!img || !canvas)
        return;
      const draw = () => {
        if (!img.naturalWidth)
          return;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      };
      if (img.complete && img.naturalWidth > 0) {
        draw();
      } else {
        img.addEventListener("load", draw, { once: true });
      }
    });
  }
  escapeAttr(text) {
    return text.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
}

// app/javascript/controllers/message_actions_controller.js
class message_actions_controller_default extends Controller {
  connect() {
    this._onContextMenu = this._onContextMenu.bind(this);
    this._dismiss = this._dismiss.bind(this);
    this._isTouchDevice = false;
    this._onFirstTouch = () => {
      this._isTouchDevice = true;
    };
    this.element.addEventListener("touchstart", this._onFirstTouch, { passive: true, once: false });
    this.element.addEventListener("contextmenu", this._onContextMenu);
  }
  disconnect() {
    this.element.removeEventListener("contextmenu", this._onContextMenu);
    this.element.removeEventListener("touchstart", this._onFirstTouch);
    this._removeSheet();
  }
  _onContextMenu(e) {
    if (!this._isTouchDevice)
      return;
    const msgEl = e.target.closest("[data-message-id]");
    if (!msgEl || msgEl.dataset.systemMessage)
      return;
    const interactive = e.target.closest("a, button, video, audio, input, textarea");
    if (interactive)
      return;
    e.preventDefault();
    if (navigator.vibrate)
      navigator.vibrate(30);
    this._showSheet(msgEl);
  }
  _showSheet(msgEl) {
    this._removeSheet();
    const messageId = msgEl.dataset.messageId;
    const authorEl = msgEl.querySelector("[style*='color:']");
    const authorName = authorEl?.textContent?.trim() || "Unknown";
    const contentEl = msgEl.querySelector(".message-content");
    const rawContent = contentEl?.dataset?.rawContent || contentEl?.textContent?.trim() || "";
    const preview = rawContent.replace(/```\w*\n?/g, "").replace(/```/g, "").trim().slice(0, 80);
    const isDM = !!document.querySelector("[data-controller*='dm-message-form']");
    const backdrop = document.createElement("div");
    backdrop.className = "modal-overlay fixed inset-0 bg-black/50 z-[100]";
    backdrop.addEventListener("click", this._dismiss);
    const sheet = document.createElement("div");
    sheet.className = "fixed bottom-0 left-0 right-0 z-[101] bg-gray-800 rounded-t-2xl shadow-2xl border-t border-gray-700 context-pop";
    sheet.innerHTML = `
      <div class="w-10 h-1 bg-gray-600 rounded-full mx-auto mt-3 mb-2"></div>
      <div class="px-4 pb-2">
        <p class="text-xs text-gray-400 truncate mb-3">${this._escapeHtml(preview)}</p>
      </div>
      <div class="px-2 pb-6 space-y-1">
        <button data-sheet-action="reply" class="flex items-center w-full px-4 py-3 text-sm text-gray-200 hover:bg-gray-700 rounded-lg active:bg-gray-600 transition">
          <svg class="w-5 h-5 mr-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6"/></svg>
          Reply
        </button>
        ${isDM ? "" : `<button data-sheet-action="react" class="flex items-center w-full px-4 py-3 text-sm text-gray-200 hover:bg-gray-700 rounded-lg active:bg-gray-600 transition">
          <svg class="w-5 h-5 mr-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          Add Reaction
        </button>`}
        <button data-sheet-action="copy" class="flex items-center w-full px-4 py-3 text-sm text-gray-200 hover:bg-gray-700 rounded-lg active:bg-gray-600 transition">
          <svg class="w-5 h-5 mr-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
          Copy Text
        </button>
      </div>
    `;
    sheet.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-sheet-action]");
      if (!btn)
        return;
      const action = btn.dataset.sheetAction;
      if (action === "reply") {
        document.dispatchEvent(new CustomEvent("inferno:reply", {
          detail: { messageId, authorName, preview },
          bubbles: true
        }));
      } else if (action === "react") {
        document.dispatchEvent(new CustomEvent("inferno:react", {
          detail: { messageId },
          bubbles: true
        }));
      } else if (action === "copy") {
        navigator.clipboard?.writeText(rawContent).catch(() => {
        });
      }
      this._dismiss();
    });
    document.body.appendChild(backdrop);
    document.body.appendChild(sheet);
    this._backdrop = backdrop;
    this._sheet = sheet;
    document.body.style.overflow = "hidden";
  }
  _dismiss() {
    this._removeSheet();
  }
  _removeSheet() {
    if (this._backdrop) {
      this._backdrop.remove();
      this._backdrop = null;
    }
    if (this._sheet) {
      this._sheet.remove();
      this._sheet = null;
    }
    document.body.style.overflow = "";
  }
  _escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }
}

// app/javascript/controllers/settings_sidebar_controller.js
class settings_sidebar_controller_default extends Controller {
  static targets = ["sidebar", "backdrop"];
  open() {
    this.sidebarTarget.classList.remove("hidden");
    if (this.hasBackdropTarget)
      this.backdropTarget.classList.remove("hidden");
  }
  close() {
    this.sidebarTarget.classList.add("hidden");
    if (this.hasBackdropTarget)
      this.backdropTarget.classList.add("hidden");
  }
}

// app/javascript/controllers/dirty_form_controller.js
class dirty_form_controller_default extends Controller {
  static targets = ["saveBar"];
  connect() {
    this._snapshot = this._captureState();
    this._onChange = this._checkDirty.bind(this);
    this.element.addEventListener("input", this._onChange);
    this.element.addEventListener("change", this._onChange);
  }
  disconnect() {
    this.element.removeEventListener("input", this._onChange);
    this.element.removeEventListener("change", this._onChange);
  }
  reset() {
    const elements = this.element.elements;
    for (let i = 0;i < elements.length; i++) {
      const el = elements[i];
      if (!el.name || !(el.name in this._snapshot))
        continue;
      if (el.type === "checkbox") {
        el.checked = this._snapshot[el.name];
      } else {
        el.value = this._snapshot[el.name];
      }
    }
    this._checkDirty();
  }
  _captureState() {
    const state = {};
    const elements = this.element.elements;
    for (let i = 0;i < elements.length; i++) {
      const el = elements[i];
      if (!el.name)
        continue;
      if (el.type === "checkbox") {
        state[el.name] = el.checked;
      } else {
        state[el.name] = el.value;
      }
    }
    return state;
  }
  _checkDirty() {
    const current = this._captureState();
    let dirty = false;
    for (const key in this._snapshot) {
      if (this._snapshot[key] !== current[key]) {
        dirty = true;
        break;
      }
    }
    if (this.hasSaveBarTarget) {
      if (dirty) {
        this.saveBarTarget.style.display = "";
        requestAnimationFrame(() => {
          this.saveBarTarget.style.opacity = "1";
          this.saveBarTarget.style.transform = "translateY(0)";
        });
      } else {
        this.saveBarTarget.style.opacity = "0";
        this.saveBarTarget.style.transform = "translateY(100%)";
        setTimeout(() => {
          if (!this._isDirty())
            this.saveBarTarget.style.display = "none";
        }, 200);
      }
    }
  }
  _isDirty() {
    const current = this._captureState();
    for (const key in this._snapshot) {
      if (this._snapshot[key] !== current[key])
        return true;
    }
    return false;
  }
}

// app/javascript/controllers/frame_loading_controller.js
class frame_loading_controller_default extends Controller {
  connect() {
    this._onBeforeFetch = this._handleBeforeFetch.bind(this);
    document.addEventListener("turbo:before-fetch-request", this._onBeforeFetch);
  }
  disconnect() {
    document.removeEventListener("turbo:before-fetch-request", this._onBeforeFetch);
  }
  _handleBeforeFetch(e) {
    if (e.target.id !== "main-content")
      return;
    const method = e.detail?.fetchOptions?.method;
    if (method && method.toUpperCase() !== "GET")
      return;
    this._showSkeleton(e.target);
  }
  _showSkeleton(frame) {
    const msgs = Array.from({ length: 6 }, (_, i) => {
      const nameW = ["w-20", "w-28", "w-24", "w-32", "w-20", "w-36"][i];
      const lineW = ["w-64 sm:w-80", "w-48 sm:w-64", "w-56 sm:w-72", "w-40 sm:w-56", "w-72 sm:w-96", "w-44 sm:w-60"][i];
      return `<div class="flex items-start gap-3 px-4">
        <div class="w-10 h-10 bg-gray-600 rounded-full shrink-0"></div>
        <div class="space-y-2 flex-1 min-w-0">
          <div class="flex items-center gap-2">
            <div class="h-3.5 bg-gray-600 rounded ${nameW}"></div>
            <div class="h-3 bg-gray-600/40 rounded w-10"></div>
          </div>
          <div class="h-3.5 bg-gray-600/30 rounded ${lineW} max-w-full"></div>
        </div>
      </div>`;
    }).join("");
    frame.innerHTML = `
      <div class="flex flex-col flex-1 min-h-0 animate-pulse">
        <div class="flex items-center h-12 px-4 border-b border-gray-900 shrink-0">
          <div class="w-5 h-5 bg-gray-600 rounded mr-2"></div>
          <div class="h-4 bg-gray-600 rounded w-28"></div>
        </div>
        <div class="flex-1 overflow-hidden flex flex-col justify-end py-4 space-y-5">
          ${msgs}
        </div>
        <div class="px-4 pb-4 pt-2">
          <div class="h-11 bg-gray-600/30 rounded-lg"></div>
        </div>
      </div>`;
  }
}

// app/javascript/controllers/voice_channel_controller.js
class voice_channel_controller_default extends Controller {
  static targets = ["statusText", "channelName", "muteBtn", "deafenBtn", "muteIcon", "deafenIcon"];
  static values = {
    serverId: String,
    connected: { type: Boolean, default: false },
    channelId: { type: String, default: "" },
    channelName: { type: String, default: "" },
    selfMute: { type: Boolean, default: false },
    selfDeaf: { type: Boolean, default: false }
  };
  connect() {
    this.room = null;
    this.muted = false;
    this.deafened = false;
    this.channelId = null;
    this.channelDisplayName = null;
    this._onJoinRequest = (e2) => this.handleJoinRequest(e2.detail);
    window.addEventListener("voice:join", this._onJoinRequest);
    this._onDisconnectRequest = () => this.disconnectVoice();
    window.addEventListener("voice:disconnect", this._onDisconnectRequest);
    this._onForceDisconnect = () => this.handleForceDisconnect();
    window.addEventListener("voice:force-disconnect", this._onForceDisconnect);
    this._onForceMove = (e2) => this.handleForceMove(e2.detail);
    window.addEventListener("voice:force-move", this._onForceMove);
    this._onServerMute = (e2) => this.handleServerMute(e2.detail);
    window.addEventListener("voice:server-mute", this._onServerMute);
    this._onServerDeafen = (e2) => this.handleServerDeafen(e2.detail);
    window.addEventListener("voice:server-deafen", this._onServerDeafen);
    this.serverMuted = false;
    this.serverDeafened = false;
    if (this.connectedValue) {
      this.channelId = this.channelIdValue;
      this.channelDisplayName = this.channelNameValue;
      this.muted = this.selfMuteValue;
      this.deafened = this.selfDeafValue;
      if (this.hasChannelNameTarget) {
        this.channelNameTarget.textContent = this.channelDisplayName;
      }
      this.updateMuteUI();
      this.updateDeafenUI();
      this.reconnectToLiveKit();
    }
  }
  disconnect() {
    window.removeEventListener("voice:join", this._onJoinRequest);
    window.removeEventListener("voice:disconnect", this._onDisconnectRequest);
    window.removeEventListener("voice:force-disconnect", this._onForceDisconnect);
    window.removeEventListener("voice:force-move", this._onForceMove);
    window.removeEventListener("voice:server-mute", this._onServerMute);
    window.removeEventListener("voice:server-deafen", this._onServerDeafen);
    if (this.room) {
      this.room.disconnect();
      this.room = null;
    }
  }
  async handleJoinRequest({ channelId, serverId }) {
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      let micStream = null;
      if (!this.muted) {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          console.warn("[Voice] navigator.mediaDevices unavailable — requires HTTPS or localhost");
          this.showToast("Microphone requires a secure connection (HTTPS or localhost)", true);
          this.muted = true;
          this.updateMuteUI();
        } else {
          try {
            micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            console.log("[Voice] Microphone permission granted");
          } catch (micErr) {
            console.warn("[Voice] Microphone denied:", micErr.name, micErr.message);
            this.muted = true;
            this.updateMuteUI();
            if (micErr.name === "NotAllowedError") {
              this.showToast("Microphone blocked — check browser permissions", true);
            } else {
              this.showToast("Microphone unavailable, joining as listener", true);
            }
          }
        }
      }
      const res = await fetch(`/servers/${serverId}/channels/${channelId}/join_voice`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        const data2 = await res.json();
        this.showToast(data2.error || "Failed to join voice channel", true);
        if (micStream)
          micStream.getTracks().forEach((t) => t.stop());
        return;
      }
      const data = await res.json();
      this.channelId = channelId;
      this.channelDisplayName = document.querySelector(`a[data-channel-id="${channelId}"] span.truncate`)?.textContent || "Voice";
      if (micStream)
        micStream.getTracks().forEach((t) => t.stop());
      const connected = await this.connectToLiveKit(data.url, data.token);
      if (!connected) {
        this.showToast("Voice connection failed", true);
        await this._leaveServerVoiceState();
        this.channelId = null;
        return;
      }
      this.showControlsBar();
      this.addSidebarParticipant(channelId, data);
      this.updateMainViewConnected(data);
    } catch (err) {
      console.error("Failed to join voice:", err);
      this.showToast("Failed to join voice channel", true);
    }
  }
  async connectToLiveKit(url, token) {
    try {
      if (this.room) {
        try {
          this.room.disconnect();
        } catch {
        }
        this.room = null;
      }
      document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
      const { Room: Room2, RoomEvent: RoomEvent2, Track: Track2 } = await Promise.resolve().then(() => (init_livekit_client_esm(), exports_livekit_client_esm));
      this.room = new Room2({
        audioCaptureDefaults: {
          autoGainControl: true,
          echoCancellation: true,
          noiseSuppression: true
        }
      });
      this.room.on(RoomEvent2.TrackSubscribed, (track, publication, participant) => {
        console.log(`[Voice] Track subscribed: ${track.kind} from ${participant.identity}`);
        if (track.kind === Track2.Kind.Audio) {
          const stale = document.getElementById(`voice-audio-${participant.identity}`);
          if (stale)
            stale.remove();
          const el = track.attach();
          el.id = `voice-audio-${participant.identity}`;
          document.body.appendChild(el);
          this.room.startAudio().then(() => {
            el.play().catch(() => {
            });
          });
        }
      });
      this.room.on(RoomEvent2.TrackUnsubscribed, (track, publication, participant) => {
        console.log(`[Voice] Track unsubscribed: ${track.kind} from ${participant.identity}`);
        track.detach().forEach((el) => el.remove());
        const leftover = document.getElementById(`voice-audio-${participant.identity}`);
        if (leftover)
          leftover.remove();
      });
      this.room.on(RoomEvent2.Disconnected, () => {
        console.log("[Voice] Disconnected from room");
        document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
        this.handleDisconnected();
      });
      this.room.on(RoomEvent2.Reconnecting, () => {
        console.log("[Voice] Reconnecting...");
        if (this.hasStatusTextTarget) {
          this.statusTextTarget.textContent = "Reconnecting...";
          this.statusTextTarget.classList.remove("text-green-500");
          this.statusTextTarget.classList.add("text-yellow-500");
        }
      });
      this.room.on(RoomEvent2.Reconnected, () => {
        console.log("[Voice] Reconnected");
        if (this.hasStatusTextTarget) {
          this.statusTextTarget.textContent = "Voice Connected";
          this.statusTextTarget.classList.remove("text-yellow-500");
          this.statusTextTarget.classList.add("text-green-500");
        }
      });
      this.room.on(RoomEvent2.ParticipantConnected, (participant) => {
        console.log(`[Voice] Participant connected: ${participant.identity}`);
      });
      this.room.on(RoomEvent2.ParticipantDisconnected, (participant) => {
        console.log(`[Voice] Participant disconnected: ${participant.identity}`);
      });
      console.log(`[Voice] Connecting to ${url}...`);
      await this.room.connect(url, token);
      console.log(`[Voice] Connected! Room: ${this.room.name}, Participants: ${this.room.remoteParticipants.size}`);
      try {
        await this.room.startAudio();
        console.log("[Voice] Audio started (autoplay unlocked)");
      } catch {
        console.log("[Voice] Audio autoplay blocked — will unlock on first interaction");
        this._setupAudioUnlock();
      }
      if (!this.muted) {
        try {
          await this.room.localParticipant.setMicrophoneEnabled(true);
          console.log("[Voice] Microphone enabled");
        } catch (micErr) {
          console.warn("[Voice] Microphone access denied:", micErr.message);
          this.muted = true;
          this.updateMuteUI();
        }
      } else {
        console.log("[Voice] Microphone stays muted");
      }
      this._attachExistingTracks();
      return true;
    } catch (err) {
      console.error("[Voice] LiveKit connection failed:", err);
      return false;
    }
  }
  async _leaveServerVoiceState() {
    if (!this.channelId)
      return;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      await fetch(`/servers/${this.serverIdValue}/channels/${this.channelId}/leave_voice`, {
        method: "DELETE",
        headers: { "X-CSRF-Token": csrf }
      });
    } catch (err) {
      console.error("[Voice] Failed to leave voice state:", err);
    }
  }
  _cleanUpAfterFailedReconnect() {
    if (this.room) {
      try {
        this.room.disconnect();
      } catch {
      }
      this.room = null;
    }
    document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
    this._leaveServerVoiceState();
    const currentUserId = document.body.dataset.currentUserId;
    if (this.channelId && currentUserId) {
      this.removeSidebarParticipant(this.channelId, currentUserId);
    }
    this.hideControlsBar();
    this.updateMainViewDisconnected();
    this.muted = false;
    this.deafened = false;
    this.channelId = null;
  }
  _setupAudioUnlock() {
    const unlock = async () => {
      if (!this.room)
        return;
      try {
        await this.room.startAudio();
        console.log("[Voice] Audio unlocked via user interaction");
        document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => {
          el.play().catch(() => {
          });
        });
      } catch (e2) {
        console.warn("[Voice] Audio unlock failed:", e2);
      }
      document.removeEventListener("click", unlock, true);
      document.removeEventListener("keydown", unlock, true);
    };
    document.addEventListener("click", unlock, true);
    document.addEventListener("keydown", unlock, true);
  }
  _attachExistingTracks() {
    if (!this.room)
      return;
    this.room.remoteParticipants.forEach((participant) => {
      participant.audioTrackPublications.forEach((pub) => {
        if (pub.track && pub.isSubscribed) {
          console.log(`[Voice] Attaching existing audio track from ${participant.identity}`);
          const existing = document.getElementById(`voice-audio-${participant.identity}`);
          if (existing)
            existing.remove();
          const el = pub.track.attach();
          el.id = `voice-audio-${participant.identity}`;
          document.body.appendChild(el);
          el.play().catch(() => {
          });
        }
      });
    });
  }
  async reconnectToLiveKit() {
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/channels/${this.channelId}/refresh_voice_token`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        console.warn("[Voice] Failed to refresh token, cleaning up");
        this._cleanUpAfterFailedReconnect();
        return;
      }
      const data = await res.json();
      const connected = await this.connectToLiveKit(data.url, data.token);
      if (!connected) {
        console.warn("[Voice] LiveKit connection failed on reconnect, cleaning up");
        this._cleanUpAfterFailedReconnect();
      }
    } catch (err) {
      console.error("[Voice] Failed to reconnect:", err);
      this._cleanUpAfterFailedReconnect();
    }
  }
  async disconnectVoice() {
    if (this.room) {
      this.room.disconnect();
      this.room = null;
    }
    document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
    if (this.channelId) {
      const serverId = this.serverIdValue;
      const csrf = document.querySelector("meta[name=csrf-token]")?.content;
      try {
        await fetch(`/servers/${serverId}/channels/${this.channelId}/leave_voice`, {
          method: "DELETE",
          headers: { "X-CSRF-Token": csrf }
        });
      } catch (err) {
        console.error("Failed to leave voice:", err);
      }
    }
    const currentUserId = document.body.dataset.currentUserId;
    if (this.channelId && currentUserId) {
      this.removeSidebarParticipant(this.channelId, currentUserId);
    }
    this.hideControlsBar();
    this.updateMainViewDisconnected();
    this.muted = false;
    this.deafened = false;
    this.channelId = null;
  }
  leave() {
    this.disconnectVoice();
  }
  async toggleMute() {
    this.muted = !this.muted;
    try {
      if (this.room?.localParticipant) {
        await this.room.localParticipant.setMicrophoneEnabled(!this.muted);
      }
    } catch (err) {
      console.warn("[Voice] setMicrophoneEnabled failed:", err.message);
    }
    this.updateMuteUI();
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      await fetch("/voice_states/self_mute", {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
    } catch (err) {
      console.error("Failed to update mute state:", err);
    }
  }
  async toggleDeafen() {
    this.deafened = !this.deafened;
    if (this.deafened)
      this.muted = true;
    try {
      if (this.room?.localParticipant) {
        await this.room.localParticipant.setMicrophoneEnabled(!this.muted);
      }
    } catch (err) {
      console.warn("[Voice] setMicrophoneEnabled failed:", err.message);
    }
    if (this.room) {
      this.room.remoteParticipants.forEach((participant) => {
        participant.audioTrackPublications.forEach((pub) => {
          try {
            if (pub.track) {
              const mst = pub.track.mediaStreamTrack;
              if (mst)
                mst.enabled = !this.deafened;
            }
          } catch (err) {
            console.warn("[Voice] Failed to toggle remote track:", err.message);
          }
        });
      });
      document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => {
        el.muted = this.deafened;
      });
    }
    this.updateMuteUI();
    this.updateDeafenUI();
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch("/voice_states/self_deafen", {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (res.ok) {
        const data = await res.json();
        this.muted = data.self_mute;
        this.deafened = data.self_deaf;
        this.updateMuteUI();
        this.updateDeafenUI();
      }
    } catch (err) {
      console.error("Failed to update deafen state:", err);
    }
  }
  handleDisconnected() {
    this.room = null;
    const currentUserId = document.body.dataset.currentUserId;
    if (this.channelId && currentUserId) {
      this.removeSidebarParticipant(this.channelId, currentUserId);
    }
    this.hideControlsBar();
    this.updateMainViewDisconnected();
    this.muted = false;
    this.deafened = false;
    this.channelId = null;
  }
  showControlsBar() {
    this.element.classList.remove("hidden");
    this.connectedValue = true;
    this.channelIdValue = this.channelId || "";
    this.channelNameValue = this.channelDisplayName || "";
    if (this.hasChannelNameTarget) {
      this.channelNameTarget.textContent = this.channelDisplayName || "Voice Channel";
    }
    if (this.hasStatusTextTarget) {
      this.statusTextTarget.textContent = "Voice Connected";
      this.statusTextTarget.classList.add("text-green-500");
      this.statusTextTarget.classList.remove("text-yellow-500");
    }
  }
  hideControlsBar() {
    this.element.classList.add("hidden");
    this.connectedValue = false;
    this.channelIdValue = "";
    this.channelNameValue = "";
  }
  addSidebarParticipant(channelId, data) {
    const channelLink = document.querySelector(`a[data-channel-id="${channelId}"]`);
    if (!channelLink)
      return;
    let container = document.querySelector(`[data-voice-channel-participants="${channelId}"]`);
    if (!container) {
      container = document.createElement("div");
      container.className = "voice-participants";
      container.dataset.voiceChannelParticipants = channelId;
      channelLink.insertAdjacentElement("afterend", container);
    }
    if (container.querySelector(`[data-voice-user-id="${data.user_id}"]`))
      return;
    if (data.sidebar_html) {
      container.insertAdjacentHTML("beforeend", data.sidebar_html);
    }
  }
  removeSidebarParticipant(channelId, userId) {
    const container = document.querySelector(`[data-voice-channel-participants="${channelId}"]`);
    if (!container)
      return;
    const el = container.querySelector(`[data-voice-user-id="${userId}"]`);
    if (el)
      el.remove();
    if (!container.children.length)
      container.remove();
  }
  updateMainViewConnected(data) {
    const joinBtn = document.querySelector("[data-voice-join-btn]");
    if (joinBtn) {
      joinBtn.outerHTML = `<p class="text-green-400 text-sm font-medium" data-voice-connected-text>You're connected to this voice channel</p>`;
    }
    const emptyState = document.querySelector("[data-voice-empty-state]");
    const gridContainer = document.querySelector("[data-voice-participant-grid]");
    const cardHtml = this.buildParticipantCard(data);
    if (emptyState) {
      emptyState.outerHTML = `<div class="flex-1 p-3 overflow-y-auto" data-voice-participant-grid><div class="voice-grid h-full">${cardHtml}</div></div>`;
    } else if (gridContainer) {
      const grid = gridContainer.querySelector(".voice-grid") || gridContainer;
      if (!grid.querySelector(`[data-voice-participant-id="${data.user_id}"]`)) {
        grid.insertAdjacentHTML("beforeend", cardHtml);
      }
    }
  }
  updateMainViewDisconnected() {
    const currentUserId = document.body.dataset.currentUserId;
    if (currentUserId) {
      const card = document.querySelector(`[data-voice-participant-id="${currentUserId}"]`);
      if (card)
        card.remove();
    }
    const gridContainer = document.querySelector("[data-voice-participant-grid]");
    const voiceGrid = gridContainer?.querySelector(".voice-grid");
    if (gridContainer && voiceGrid && voiceGrid.children.length === 0) {
      const wrapper = document.querySelector("[data-current-channel-id]");
      const channelName = wrapper?.querySelector("h1")?.textContent || "Voice Channel";
      gridContainer.outerHTML = `
        <div class="flex-1 flex flex-col items-center justify-center p-8" data-voice-empty-state>
          <div class="w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6" style="background: rgba(255,255,255,0.05);">
            <svg class="w-12 h-12 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M15.536 8.464a5 5 0 010 7.072M12 6v12m-3.536-2.464a5 5 0 010-7.072M18.364 5.636a9 9 0 010 12.728M5.636 18.364a9 9 0 010-12.728"/></svg>
          </div>
          <h2 class="text-xl font-bold text-white mb-1">${this.escapeHtml(channelName)}</h2>
          <p class="text-gray-500 text-sm">No one is in this channel yet.</p>
        </div>`;
    }
    const connectedText = document.querySelector("[data-voice-connected-text]");
    if (connectedText) {
      const wrapper = document.querySelector("[data-current-channel-id]");
      const channelId = wrapper?.dataset.currentChannelId || "";
      const serverId = wrapper?.dataset.currentServerId || "";
      connectedText.outerHTML = `
        <button type="button"
                class="px-6 py-2.5 bg-green-600 hover:bg-green-500 text-white font-semibold rounded-full transition flex items-center gap-2 cursor-pointer text-sm"
                data-voice-join-btn
                onclick="window.dispatchEvent(new CustomEvent('voice:join', { detail: { channelId: '${channelId}', serverId: '${serverId}' } }))">
          <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.536 8.464a5 5 0 010 7.072M12 6v12m-3.536-2.464a5 5 0 010-7.072"/></svg>
          Join Voice
        </button>`;
    }
  }
  updateMuteUI() {
    if (!this.hasMuteBtnTarget)
      return;
    if (this.muted) {
      this.muteBtnTarget.classList.add("text-red-400");
      this.muteBtnTarget.classList.remove("text-gray-300");
      if (this.hasMuteIconTarget) {
        this.muteIconTarget.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3l18 18"/>';
      }
    } else {
      this.muteBtnTarget.classList.remove("text-red-400");
      this.muteBtnTarget.classList.add("text-gray-300");
      if (this.hasMuteIconTarget) {
        this.muteIconTarget.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/>';
      }
    }
  }
  updateDeafenUI() {
    if (!this.hasDeafenBtnTarget)
      return;
    if (this.deafened) {
      this.deafenBtnTarget.classList.add("text-red-400");
      this.deafenBtnTarget.classList.remove("text-gray-300");
      if (this.hasDeafenIconTarget) {
        this.deafenIconTarget.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2"/>';
      }
    } else {
      this.deafenBtnTarget.classList.remove("text-red-400");
      this.deafenBtnTarget.classList.add("text-gray-300");
      if (this.hasDeafenIconTarget) {
        this.deafenIconTarget.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z M15.54 8.46a5 5 0 010 7.07"/>';
      }
    }
  }
  buildParticipantCard(data) {
    const color = data.profile_color || "#1e1c1b";
    const initial = data.username?.[0]?.toUpperCase() || "?";
    const avatarHtml = data.avatar_url ? `<img src="${data.avatar_url}" class="voice-avatar" />` : `<div class="voice-avatar-fallback" style="background-color: color-mix(in srgb, ${color}, white 20%)">${initial}</div>`;
    const vsId = data.voice_state_id || "";
    return `
      <div class="voice-card group" data-voice-participant-id="${data.user_id}" data-voice-state-id="${vsId}" data-action="contextmenu->voice-context#show" style="--card-color: ${color}">
        <div class="voice-card-inner">
          <div class="voice-avatar-wrapper">${avatarHtml}</div>
          <div class="voice-username-pill">
            <span class="truncate">${this.escapeHtml(data.username)}</span>
          </div>
        </div>
      </div>`;
  }
  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
  handleForceDisconnect() {
    if (this.room) {
      this.room.disconnect();
      this.room = null;
    }
    document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
    this.hideControlsBar();
    this.updateMainViewDisconnected();
    this.muted = false;
    this.deafened = false;
    this.serverMuted = false;
    this.serverDeafened = false;
    this.channelId = null;
    this.showToast("You were disconnected from voice");
  }
  async handleForceMove({ toChannelId, toChannelName, voiceStateId }) {
    if (this.room) {
      this.room.disconnect();
      this.room = null;
    }
    document.querySelectorAll('[id^="voice-audio-"]').forEach((el) => el.remove());
    this.channelId = toChannelId;
    this.channelDisplayName = toChannelName || "Voice";
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/servers/${this.serverIdValue}/channels/${toChannelId}/refresh_voice_token`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        this.hideControlsBar();
        this.updateMainViewDisconnected();
        this.channelId = null;
        this.showToast("Failed to join new voice channel", true);
        return;
      }
      const data = await res.json();
      const connected = await this.connectToLiveKit(data.url, data.token);
      if (!connected) {
        this.hideControlsBar();
        this.updateMainViewDisconnected();
        this.channelId = null;
        this.showToast("Failed to connect to new voice channel", true);
        return;
      }
      this.showControlsBar();
      this.showToast(`You were moved to #${toChannelName || "voice"}`);
    } catch (err) {
      console.error("[Voice] Force move failed:", err);
      this.hideControlsBar();
      this.channelId = null;
      this.showToast("Failed to join new voice channel", true);
    }
  }
  async handleServerMute({ serverMute }) {
    this.serverMuted = serverMute;
    if (serverMute) {
      if (this.room?.localParticipant) {
        await this.room.localParticipant.setMicrophoneEnabled(false);
      }
      this.muted = true;
      this.updateMuteUI();
    } else {
      if (!this.muted || this.serverMuted === false) {
      }
    }
  }
  async handleServerDeafen({ serverDeaf }) {
    this.serverDeafened = serverDeaf;
    if (serverDeaf) {
      if (this.room?.localParticipant) {
        await this.room.localParticipant.setMicrophoneEnabled(false);
      }
      this.muted = true;
      this.deafened = true;
      if (this.room) {
        this.room.remoteParticipants.forEach((participant) => {
          participant.audioTrackPublications.forEach((pub) => {
            if (pub.track) {
              pub.track.mediaStreamTrack.enabled = false;
            }
          });
        });
      }
      this.updateMuteUI();
      this.updateDeafenUI();
    } else {
      this.deafened = false;
      if (this.room) {
        this.room.remoteParticipants.forEach((participant) => {
          participant.audioTrackPublications.forEach((pub) => {
            if (pub.track) {
              pub.track.mediaStreamTrack.enabled = true;
            }
          });
        });
      }
      this.updateDeafenUI();
    }
  }
  showToast(msg, isError = false) {
    const toast = document.createElement("div");
    toast.className = `fixed bottom-6 right-6 ${isError ? "bg-red-600" : "bg-green-600"} text-white px-4 py-2 rounded-lg shadow-lg z-[200] text-sm font-medium context-pop`;
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.style.transition = "opacity 0.3s";
      toast.style.opacity = "0";
      setTimeout(() => toast.remove(), 300);
    }, 3000);
  }
}

// app/javascript/controllers/voice_context_controller.js
class voice_context_controller_default extends Controller {
  static values = { serverId: String };
  connect() {
    this.menu = null;
    this.moveDropdown = null;
    this.boundClose = this.closeMenu.bind(this);
  }
  disconnect() {
    this.closeMenu();
  }
  async show(event) {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    const target = event.currentTarget;
    const voiceStateId = target.dataset.voiceStateId;
    if (!voiceStateId)
      return;
    const response = await fetch(`/voice_states/${voiceStateId}/context_menu`, {
      headers: { "X-Requested-With": "XMLHttpRequest" }
    });
    if (!response.ok)
      return;
    const html = await response.text();
    this.menu = document.createElement("div");
    this.menu.className = "fixed z-[60] context-pop";
    this.menu.setAttribute("data-context-menu", "voice");
    this.menu.innerHTML = html;
    let left = event.clientX;
    let top = event.clientY;
    if (left + 220 > window.innerWidth)
      left = window.innerWidth - 220;
    if (top + 300 > window.innerHeight)
      top = window.innerHeight - 300;
    this.menu.style.left = `${left}px`;
    this.menu.style.top = `${top}px`;
    document.body.appendChild(this.menu);
    this.bindMenuActions();
    setTimeout(() => document.addEventListener("click", this.boundClose), 10);
  }
  bindMenuActions() {
    if (!this.menu)
      return;
    this.menu.querySelectorAll("[data-context-action]").forEach((btn) => {
      const action = btn.dataset.contextAction;
      if (action === "serverMute") {
        btn.addEventListener("click", (e2) => this.handleServerMute(e2));
      } else if (action === "serverDeafen") {
        btn.addEventListener("click", (e2) => this.handleServerDeafen(e2));
      } else if (action === "kick") {
        btn.addEventListener("click", (e2) => this.handleKick(e2));
      } else if (action === "showMoveTargets") {
        btn.addEventListener("click", (e2) => this.showMoveTargets(e2));
      }
    });
  }
  async handleServerMute(event) {
    event.stopPropagation();
    const voiceStateId = event.currentTarget.dataset.voiceStateId;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/voice_states/${voiceStateId}/server_mute`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        const data = await res.json();
        this.showToast(data.error || "Failed to toggle server mute", true);
      }
    } catch (err) {
      this.showToast("Failed to toggle server mute", true);
    }
    this.closeMenu();
  }
  async handleServerDeafen(event) {
    event.stopPropagation();
    const voiceStateId = event.currentTarget.dataset.voiceStateId;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/voice_states/${voiceStateId}/server_deafen`, {
        method: "PATCH",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        const data = await res.json();
        this.showToast(data.error || "Failed to toggle server deafen", true);
      }
    } catch (err) {
      this.showToast("Failed to toggle server deafen", true);
    }
    this.closeMenu();
  }
  async handleKick(event) {
    event.stopPropagation();
    const voiceStateId = event.currentTarget.dataset.voiceStateId;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/voice_states/${voiceStateId}/kick`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" }
      });
      if (!res.ok) {
        const data = await res.json();
        this.showToast(data.error || "Failed to disconnect user", true);
      }
    } catch (err) {
      this.showToast("Failed to disconnect user", true);
    }
    this.closeMenu();
  }
  showMoveTargets(event) {
    event.preventDefault();
    event.stopPropagation();
    if (this.moveDropdown) {
      this.moveDropdown.remove();
      this.moveDropdown = null;
      return;
    }
    const btn = event.currentTarget;
    const voiceStateId = btn.dataset.voiceStateId;
    const channels = JSON.parse(btn.dataset.channels || "[]");
    if (!this.menu || !channels.length)
      return;
    this.moveDropdown = document.createElement("div");
    this.moveDropdown.className = "absolute z-[70] w-48 bg-gray-900 rounded-lg shadow-2xl border border-gray-700 py-1.5 text-sm max-h-64 overflow-y-auto context-pop";
    const wrapper = btn.closest(".context-move-wrapper");
    const btnRect = wrapper.getBoundingClientRect();
    let ddLeft = btnRect.right + 4;
    if (ddLeft + 200 > window.innerWidth) {
      ddLeft = btnRect.left - 200;
    }
    let ddTop = btnRect.top;
    if (ddTop + 260 > window.innerHeight) {
      ddTop = window.innerHeight - 264;
    }
    this.moveDropdown.style.position = "fixed";
    this.moveDropdown.style.left = `${ddLeft}px`;
    this.moveDropdown.style.top = `${ddTop}px`;
    let html = '<p class="px-3 py-1.5 text-[10px] font-semibold text-gray-500 uppercase sticky top-0 bg-gray-900">Move to</p>';
    channels.forEach((ch) => {
      html += `<button class="flex items-center w-full px-3 py-1.5 text-gray-300 hover:bg-gray-700 hover:text-white rounded-sm"
                       data-context-action="move"
                       data-voice-state-id="${voiceStateId}"
                       data-target-channel-id="${ch.id}">
                 <svg class="w-4 h-4 text-gray-500 mr-2 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15.536 8.464a5 5 0 010 7.072M12 6v12m-3.536-2.464a5 5 0 010-7.072"/></svg>
                 <span class="truncate">${this.escapeHtml(ch.name)}</span>
               </button>`;
    });
    this.moveDropdown.innerHTML = html;
    document.body.appendChild(this.moveDropdown);
    this.moveDropdown.querySelectorAll('[data-context-action="move"]').forEach((moveBtn) => {
      moveBtn.addEventListener("click", (e2) => this.handleMove(e2));
    });
    this.moveDropdown.addEventListener("click", (e2) => e2.stopPropagation());
  }
  async handleMove(event) {
    event.stopPropagation();
    const voiceStateId = event.currentTarget.dataset.voiceStateId;
    const targetChannelId = event.currentTarget.dataset.targetChannelId;
    const csrf = document.querySelector("meta[name=csrf-token]")?.content;
    try {
      const res = await fetch(`/voice_states/${voiceStateId}/move`, {
        method: "POST",
        headers: { "X-CSRF-Token": csrf, "Content-Type": "application/json" },
        body: JSON.stringify({ target_channel_id: targetChannelId })
      });
      if (!res.ok) {
        const data = await res.json();
        this.showToast(data.error || "Failed to move user", true);
      }
    } catch (err) {
      this.showToast("Failed to move user", true);
    }
    this.closeMenu();
  }
  closeMenu(event) {
    if (this.moveDropdown) {
      if (event && this.moveDropdown.contains(event.target))
        return;
      this.moveDropdown.remove();
      this.moveDropdown = null;
    }
    if (this.menu) {
      if (event && this.menu.contains(event.target))
        return;
      this.menu.remove();
      this.menu = null;
    }
    document.removeEventListener("click", this.boundClose);
  }
  escapeHtml(text) {
    const div = document.createElement("div");
    div.textContent = text;
    return div.innerHTML;
  }
  showToast(msg, isError = false) {
    const toast = document.createElement("div");
    toast.className = `fixed bottom-6 right-6 ${isError ? "bg-red-600" : "bg-green-600"} text-white px-4 py-2 rounded-lg shadow-lg z-[200] text-sm font-medium context-pop`;
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.style.transition = "opacity 0.3s";
      toast.style.opacity = "0";
      setTimeout(() => toast.remove(), 300);
    }, 3000);
  }
}

// app/javascript/controllers/instance_sync_controller.js
class instance_sync_controller_default extends Controller {
  static values = { url: String };
  async navigate(event) {
    event.preventDefault();
    const targetUrl = this.urlValue || this.element.href;
    if (!targetUrl)
      return;
    this.showOverlay();
    try {
      const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content;
      const response = await fetch("/api/federation_sync", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrfToken
        },
        body: JSON.stringify({ target_url: targetUrl })
      });
      if (response.ok) {
        const data = await response.json();
        if (data.status === "home_unreachable") {
          this.removeStaleReference();
          this.hideOverlay();
          this.showError("That server is no longer reachable — your account may have been removed from that instance.");
          return;
        }
        this.updateOverlayStatus(data.synced || []);
        await new Promise((r2) => setTimeout(r2, 400));
      }
    } catch (e2) {
      console.warn("Instance sync failed:", e2);
    }
    window.location.href = targetUrl;
  }
  removeStaleReference() {
    const serverEl = this.element.closest("[data-server-id]");
    if (!serverEl)
      return;
    const folderList = serverEl.closest("[data-folder-server-list]");
    serverEl.remove();
    if (folderList && folderList.children.length === 0) {
      const folderEl = folderList.closest("[data-rail-item]");
      if (folderEl)
        folderEl.remove();
    }
  }
  showError(message) {
    const toast = document.createElement("div");
    toast.className = "fixed top-4 right-4 z-50 bg-red-600 text-white px-4 py-2 rounded-lg shadow-lg";
    toast.setAttribute("data-controller", "toast");
    toast.textContent = message;
    document.body.appendChild(toast);
  }
  showOverlay() {
    let overlay = document.getElementById("instance-sync-overlay");
    if (!overlay) {
      overlay = document.createElement("div");
      overlay.id = "instance-sync-overlay";
      overlay.innerHTML = `
        <div class="modal-overlay fixed inset-0 z-[9999] bg-black/70 flex items-center justify-center backdrop-blur-sm">
          <div class="bg-gray-800 rounded-xl border border-gray-700 p-6 max-w-sm w-full mx-4 shadow-2xl text-center">
            <div class="flex justify-center mb-4">
              <svg class="w-8 h-8 text-amber-400 animate-spin" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            </div>
            <h3 class="text-lg font-semibold text-white mb-1">Syncing instance data</h3>
            <p class="text-sm text-gray-400" data-sync-status>Fetching latest profile, servers, and collections...</p>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);
    }
    overlay.classList.remove("hidden");
  }
  updateOverlayStatus(synced) {
    const el = document.querySelector("[data-sync-status]");
    if (!el)
      return;
    const labels = {
      profile: "Profile",
      servers: "Servers",
      folders: "Folders",
      conversations: "Conversations",
      friends: "Friends",
      gif_collections: "GIF collections"
    };
    const names = synced.map((s) => labels[s] || s).join(", ");
    el.textContent = names.length > 0 ? `Synced: ${names}` : "Up to date";
  }
  hideOverlay() {
    const overlay = document.getElementById("instance-sync-overlay");
    if (overlay)
      overlay.classList.add("hidden");
  }
}

// app/javascript/application.js
var application = Application.start();
setConfirmMethod((message) => {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay fixed inset-0 z-[100] flex items-center justify-center bg-black/60";
    overlay.innerHTML = `
      <div class="bg-gray-800 rounded-lg shadow-2xl border border-gray-700 w-full max-w-md mx-4 overflow-hidden">
        <div class="px-5 pt-5 pb-4">
          <h3 class="text-lg font-semibold text-white mb-2">Are you sure?</h3>
          <p class="text-sm text-gray-300">${message.replace(/</g, "&lt;").replace(/>/g, "&gt;")}</p>
        </div>
        <div class="flex justify-end gap-3 px-5 py-4 bg-gray-850 bg-gray-900/50">
          <button data-action="cancel" class="px-4 py-2 text-sm font-medium text-gray-300 hover:text-white hover:underline cursor-pointer">Cancel</button>
          <button data-action="confirm" class="px-4 py-2 text-sm font-medium bg-red-600 hover:bg-red-700 text-white rounded transition cursor-pointer">Confirm</button>
        </div>
      </div>
    `;
    const cleanup = (result) => {
      overlay.remove();
      resolve(result);
    };
    overlay.addEventListener("click", (e2) => {
      if (e2.target === overlay)
        cleanup(false);
    });
    overlay.querySelector('[data-action="cancel"]').addEventListener("click", () => cleanup(false));
    overlay.querySelector('[data-action="confirm"]').addEventListener("click", () => cleanup(true));
    document.addEventListener("keydown", function handler(e2) {
      if (e2.key === "Escape") {
        document.removeEventListener("keydown", handler);
        cleanup(false);
      }
      if (e2.key === "Enter") {
        document.removeEventListener("keydown", handler);
        cleanup(true);
      }
    });
    document.body.appendChild(overlay);
    overlay.querySelector('[data-action="confirm"]').focus();
  });
});
try {
  const stored = localStorage.getItem("_emojiMap");
  if (stored) {
    window._emojiMap = JSON.parse(stored);
    window._emojiPUA = JSON.parse(localStorage.getItem("_emojiPUA") || "{}");
    window._emojiReverse = JSON.parse(localStorage.getItem("_emojiReverse") || "{}");
    window._nextPUA = parseInt(localStorage.getItem("_nextPUA") || "0") || 57344;
  }
} catch (e2) {
}
